# Cell result grids are compact: short rows, a few visible, scroll for the rest.
@dataclasses.dataclass
class Cell:
    """One notebook cell as the browser sees it."""

    id: str
    code: str = ""
    count: str = ""
    """The In[n] number: "" never run, "*" running."""
    stdout: str = ""
    text: str = ""
    error: str = ""
    trace: list[dict[str, str]] = dataclasses.field(default_factory=list)
    """Bottom of the error's traceback as styled parts (session.trace_parts / split_trace): the frame
    that raised and the error. Rendered instead of the plain error text."""
    trace_hidden: list[dict[str, str]] = dataclasses.field(default_factory=list)
    """The rest of the traceback above it, collapsed by default."""
    trace_more: str = ""
    """Label of the collapsed part, eg "4 more frames"."""
    view: ViewData = dataclasses.field(default_factory=ViewData)
    """The result's view (render.py): a grid, videos, a model's fields; kind "" when it has none."""

    def __setstate__(self, state: dict[str, Any]) -> None:
        fill_defaults(self, state)


@dataclasses.dataclass
class ChatItem:
    """One chat entry. kind: user | agent | step | ref | error."""

    kind: str
    name: str = ""
    """step: the tool; ref: the result's name (r1, r2, ...)."""
    key: str = ""
    """The row's DOM id, what State.reveal and the debug log link to: user 'turn-<n>' (the
    records of that agent turn carry it as `turn`), step 'call-<tool_call_id>'. A ref's is
    'ref-<name>' (set in reflex_kernel.ref_item)."""
    text: str = ""
    open: bool = False
    """ref only: whether the result is shown inline, under the row (collapsed by default)."""
    view: ViewData = dataclasses.field(default_factory=ViewData)
    """ref only: the result's view at slot chat:<name> while open; empty when collapsed."""
    # error only: the traceback as styled parts, as on a cell (see Cell); text keeps the plain text
    trace: list[dict[str, str]] = dataclasses.field(default_factory=list)
    trace_hidden: list[dict[str, str]] = dataclasses.field(default_factory=list)
    trace_more: str = ""

    def __setstate__(self, state: dict[str, Any]) -> None:
        fill_defaults(self, state)


@dataclasses.dataclass
class LogRow:
    """One debug-panel row (logs.rows): a record of an outside call, formatted by its kind."""

    id: str
    time: str
    kind: str
    error: bool = False
    summary: str = ""
    badges: list[str] = dataclasses.field(default_factory=list)
    details: list[dict[str, str]] = dataclasses.field(default_factory=list)
    """{"label", "text"} pairs, shown when the row is unfolded."""
    copy: str = ""
    """The whole record as JSON, for the copy button."""
    curl: str = ""
    """The request as a curl command (http / graphql records; secrets as $VARIABLES), else ""."""
    session: str = ""
    target: str = ""
    """Where the record came from, for State.reveal: a chat row ('call-<id>', 'turn-<n>'), a
    result tab ('tab:<name>') or a cell ('cell:<id>'); "" when there is none on this page."""
    target_label: str = ""

    def __setstate__(self, state: dict[str, Any]) -> None:
        fill_defaults(self, state)


def _trace_fields(parts: list[dict[str, str]]) -> dict[str, Any]:
    hidden, shown = split_trace(parts)
    frames = sum(part["kind"] == "frame" for part in hidden)
    chained = sum(part["kind"] == "chain" for part in hidden)
    label = ", ".join(
        text
        for count, text in [
            (frames, f"{frames} more frame{'s' if frames != 1 else ''}"),
            (chained, f"{chained} chained exception{'s' if chained != 1 else ''}"),
        ]
        if count
    )
    return {"trace": shown, "trace_hidden": hidden, "trace_more": label or "full traceback"}


class State(rx.State):
    # Chat is a flat list so it renders with one foreach.
    chat: list[ChatItem] = []
    streaming: str = ""
    busy: bool = False

    cells: list[Cell] = [Cell(id="c1")]
    cell_seq: int = 1
    # agent turns so far: the n of a user row's key 'turn-<n>'
    turn_seq: int = 0
    exec_count: int = 0
    running: bool = False

    # Tabs: every named value render.py has a view for; `view` is the selected one's. A view's own
    # state (filter, sort, picked video) is inside it, kept in the session by slot.
    objects: list[dict[str, str]] = []
    selected: str = ""
    view: ViewData = ViewData()
    # Panes toggled from the bottom bar.
    show_chat: bool = True
    # Only the chat at first; results also unfold inline in the chat.
    show_results: bool = False
    show_python: bool = False
    # The pane filling the window ("" = none): chat | results | python. Leaves the toggles as they were.
    zoomed: str = ""
    # A tab's right-click menu: the tab it is for ("" = closed) and where it opens.
    menu_tab: str = ""
    menu_x: int = 0
    menu_y: int = 0
    # The help panel (? in the title bar).
    show_help: bool = False
    # The Results tab bar's "+" menu (at menu_x / menu_y).
    add_menu: bool = False
    # Opened from the keyboard (Shortcut.ADD_WIDGET): shown in the middle of the window instead.
    add_menu_centered: bool = False
    # The debug panel (bug icon in the title bar, Shortcut.DEBUG): the app's outside calls (logs.py).
    # Loaded when opened, on Refresh and after a turn / form / cell finishes while it is open;
    # never pushed as calls happen, so it costs nothing while closed.
    show_debug: bool = False
    debug_rows: list[LogRow] = []
    debug_count: int = 0
    debug_stats: str = ""
    debug_kinds: list[str] = list(logs.LOG_FORMATS)
    # kinds shown ([] = all) and whether only this tab's session
    debug_shown: list[str] = []
    debug_mine: bool = False
    # only the records of one thing (State.show_logs; logs.in_focus): a tool call, an agent turn,
    # a result, a cell; "" = all. Same ids as the rows' ↖ links (State.reveal).
    debug_focus: str = ""
    debug_focus_label: str = ""

    def _session(self) -> Session:
        return get_session(self.router.session.client_token)

    def _log_context(self, origin: str, **where: str) -> Any:
        """Tag the log records of what runs inside with this tab's session and where it started
        (chat | form | view | cell). Follows asyncio tasks and asyncio.to_thread.

        where: what the debug log links back to (logs.target): turn='turn-<n>' for a chat
        turn, slot='tab:<name>' / 'cell:<id>' for a form, page or cell run."""
        session = logs.session_id(self.router.session.client_token)
        return logger.contextualize(session=session, origin=origin, **where)

    def _load_debug(self) -> None:
        mine = logs.session_id(self.router.session.client_token)
        # a focus is always this tab's: turn and cell ids repeat across sessions
        session = mine if self.debug_mine or self.debug_focus else ""
        name = self.debug_focus.removeprefix("tab:")
        made_by = self._session().tool_call_ids.get(name, "") if self.debug_focus.startswith("tab:") else ""
        found, self.debug_count = logs.rows(self.debug_shown, session, self.debug_focus, made_by)
        # a link only where its target is on this page: this session's records
        self.debug_rows = [
            LogRow(**row) if row["session"] == mine else LogRow(**row | {"target": "", "target_label": ""})
            for row in found
        ]
        self.debug_kinds = list(dict.fromkeys([*logs.LOG_FORMATS, *logs.kinds()]))
        self.debug_stats = logs.stats(self._session().namespace, BUILTIN_NAMES)

    def _refresh_debug(self) -> None:
        """After something finished: reload the debug panel if it is open."""
        if self.show_debug:
            self._load_debug()

    def _sync(self, prefer: str = "") -> None:
        """Re-read the session's viewable values into the tab list and redraw the selected one."""
        session = self._session()
        everything, views = session.views(), session.tabs()
        self.objects = [
            {"name": name, "shape": view.summary, "source": session.sources.get(name, "python"), "kind": view.kind}
            for name, view in views.items()
        ]
        # forget what was done to tabs that are gone
        session.ui = {
            slot: ui
            for slot, ui in session.ui.items()
            if not (
                (slot.startswith("tab:") and slot[4:] not in views)
                or (slot.startswith("chat:") and slot[5:] not in everything)
            )
        }
        # ... and the tool calls behind names that are gone or bound to something else
        session.calls = {
            key: call
            for key, call in session.calls.items()
            if key.startswith("cell:") or session.namespace.get(key) is call.value
        }
        # results open inline in the chat follow their value (a cell may have changed or deleted it)
        for name in {item.name for item in self.chat if item.open}:
            self._show(f"chat:{name}")
        if prefer in views:
            self._select(prefer)
        elif self.selected not in views:
            self._select(next(reversed(views), ""))
        self._show(f"tab:{self.selected}")

    def _select(self, name: str) -> None:
        if name != self.selected:
            # a video in the tab being left stops; it is back, paused, with the tab
            if left := self._session().ui.get(f"tab:{self.selected}"):
                left.autoplay = False
            self.selected = name
            self.view = ViewData()

    def _show(self, slot: str) -> None:
        """Redraw the view shown at a slot (the selected tab, or a cell's result) from the session."""
        kind, _, key = slot.partition(":")
        if kind == "tab":
            if key == self.selected:
                self.view = self._session().show(slot)
        elif kind == "chat":
            view = self._session().show(slot, compact=True)
            for index, item in enumerate(self.chat):
                if item.kind == "ref" and item.name == key and item.open:
                    self.chat[index] = dataclasses.replace(item, view=view)
        elif (index := self._cell_index(key)) >= 0:
            self._update(index, view=self._session().show(slot, compact=True))

    @rx.var
    def token(self) -> str:
        """This tab's session id, passed to the editor so completions use the right namespace."""
        return self.router.session.client_token

    @rx.var
    def chat_on(self) -> bool:
        """Whether the chat pane is on screen: its toggle, unless a pane is zoomed."""
        return self.zoomed == "chat" or (self.zoomed == "" and self.show_chat)

    @rx.var
    def results_on(self) -> bool:
        return self.zoomed == "results" or (self.zoomed == "" and self.show_results)

    @rx.var
    def python_on(self) -> bool:
        return self.zoomed == "python" or (self.zoomed == "" and self.show_python)

    @rx.var
    def pane_layout(self) -> str:
        """The results pane: hidden, alone (Python hidden, so it takes the full width) or split."""
        if not self.results_on:
            return "hidden"
        return "split" if self.python_on else "alone"

    @rx.var
    def chat_layout(self) -> str:
        """The chat pane: hidden, alone (nothing below it, so it takes the full height) or split."""
        if not self.chat_on:
            return "hidden"
        return "split" if self.results_on or self.python_on else "alone"

    @rx.var
    def chat_refs(self) -> list[str]:
        """Names of the results that have a tool-call row in the chat."""
        return [item.name for item in self.chat if item.kind == "ref"]

    @rx.var
    def has_objects(self) -> bool:
        return len(self.objects) > 0

    @rx.event
    def on_load(self):
        # chat saved before ChatItem existed was plain dicts
        if any(isinstance(item, dict) for item in self.chat):
            self.chat = [ChatItem(**item) if isinstance(item, dict) else item for item in self.chat]
        self._sync()

    @rx.event
    def select_object(self, name: str):
        self._reveal_results()
        if self._session().closed.pop(name, None) is not None:
            self._sync(prefer=name)  # a closed tab opens again
            return
        self._select(name)
        self._show(f"tab:{name}")

    # -- closing tabs (x, right-click menu) ---------------------------

    def _close(self, names: list[str]) -> None:
        """Close tabs. If the selected one goes, the tab to its right is selected (else the one to its left)."""
        order = [obj["name"] for obj in self.objects]
        prefer = ""
        if self.selected in names and self.selected in order:
            at = order.index(self.selected)
            rest = [name for name in order[at + 1 :] + order[:at][::-1] if name not in names]
            prefer = rest[0] if rest else ""
        self._session().close_tabs(names)
        self.menu_tab = ""
        self._sync(prefer=prefer)

    @rx.event
    def close_tab(self, name: str):
        self._close([name])

    @rx.event
    def close_other_tabs(self, name: str):
        self._close([obj["name"] for obj in self.objects if obj["name"] != name])

    @rx.event
    def close_tabs_right(self, name: str):
        order = [obj["name"] for obj in self.objects]
        if name in order:
            self._close(order[order.index(name) + 1 :])

    @rx.event
    def close_all_tabs(self):
        self._close([obj["name"] for obj in self.objects])

    @rx.event
    def open_tab_menu(self, name: str, info: dict[str, Any]):
        self.menu_tab = name
        self.menu_x, self.menu_y = int(info.get("client_x", 0)), int(info.get("client_y", 0))

    @rx.event
    def close_menus(self):
        """Close the tab menu, the "+" menu and the help panel (click outside, Escape)."""
        self.menu_tab = ""
        self.add_menu = False
        self.show_help = False
        self.show_debug = False

    @rx.event
    def show_in_chat(self, name: str):
        """Scroll the chat to the row of the tool call that returned a result, and flash it."""
        yield from self._reveal(f"ref-{name}")

    @rx.event
    def reveal(self, target: str):
        """Go to a part of the page and flash it (see _reveal)."""
        yield from self._reveal(target)

    def _reveal(self, target: str):
        """The one way the app takes you somewhere: show the pane, scroll to it, flash it
        (assets/panes.js window.reveal, the same animation everywhere).

        target: a chat row's id ('ref-<name>', 'call-<tool_call_id>', 'turn-<n>'), a result's
        tab ('tab:<name>', opened again if it was closed) or a cell ('cell:<id>').
        """
        self.menu_tab, self.add_menu, self.show_help, self.show_debug = "", False, False, False
        kind, _, key = target.partition(":")
        if kind == "tab":
            if key not in self._session().views():
                return
            self._reveal_results()
            if self._session().closed.pop(key, None) is not None:
                self._sync(prefer=key)
            else:
                self._select(key)
                self._show(target)
            element = f"tab-{key}"
        elif kind == "cell":
            self.show_python = True
            if self.zoomed not in ("", "python"):
                self.zoomed = ""
            element = f"cell-{key}"
        else:
            self.show_chat = True
            if self.zoomed not in ("", "chat"):
                self.zoomed = ""
            element = target
        yield  # let the pane show before scrolling
        yield rx.call_script(f"window.reveal && window.reveal({json.dumps(element)})")

    @rx.event
    def toggle_help(self):
        self.show_debug = False
        self.show_help = not self.show_help

    # -- debug panel (logs.py) ---------------------------------------------------

    @rx.event
    def toggle_debug(self):
        self.show_help = False
        self.show_debug = not self.show_debug
        if self.show_debug:
            self.debug_focus = self.debug_focus_label = ""  # the icon / Alt+D opens everything
            self._load_debug()
        else:
            self.debug_rows = []  # nothing big kept in the tab's state while closed

    @rx.event
    def show_logs(self, target: str):
        """Open the debug log on just the records of one thing: the reverse of a row's ↖ link.

        target: a tool call's chat row ('call-<id>'), an agent turn ('turn-<n>'), a result
        ('tab:<name>': the call that made it and its form runs) or a cell ('cell:<id>').
        """
        self.menu_tab, self.add_menu, self.show_help = "", False, False
        self.debug_focus, self.debug_focus_label = target, self._focus_label(target)
        self.show_debug = True
        self._load_debug()

    def _focus_label(self, target: str) -> str:
        """What a focus is called at the top of the debug log, eg 'tool call get_player_usage'."""
        kind, _, key = target.partition(":")
        if kind == "tab":
            return f"result {key}: the call that made it and its form runs"
        if kind == "cell":
            index = self._cell_index(key)
            count = self.cells[index].count if index >= 0 else ""
            return f"cell [{count}]" if count else "this cell"
        item = next((item for item in self.chat if item.key == target), None)
        if target.startswith("call-"):
            return f"tool call {item.name}" if item else "tool call"
        text = item.text if item else ""
        return f"chat turn: {text[:60]}{'…' if len(text) > 60 else ''}"  # noqa: PLR2004  # label length

    @rx.event
    def clear_debug_focus(self):
        self.debug_focus = self.debug_focus_label = ""
        self._load_debug()

    @rx.event
    def refresh_debug(self):
        self._load_debug()

    @rx.event
    def clear_debug(self):
        """Forget the log: this session's records when "this session only" is on, else all."""
        logs.clear(logs.session_id(self.router.session.client_token) if self.debug_mine else "")
        self._load_debug()

    @rx.event
    def toggle_debug_kind(self, kind: str):
        """A kind chip: show only the picked kinds; none picked shows all."""
        shown = self.debug_shown
        self.debug_shown = [k for k in shown if k != kind] if kind in shown else [*shown, kind]
        self._load_debug()

    @rx.event
    def toggle_debug_mine(self):
        self.debug_mine = not self.debug_mine
        self._load_debug()

    @rx.event
    def toggle_inline(self, name: str):
        """A tool result's row in the chat: show its view inline under the row, or fold it away."""
        for index, item in enumerate(self.chat):
            if item.kind == "ref" and item.name == name:
                opening = not item.open
                # folding unmounts the view (a playing video stops); opening reads it fresh
                self.chat[index] = dataclasses.replace(item, open=opening, view=ViewData())
                if opening:
                    self._show(f"chat:{name}")

    @rx.event
    async def view_event(self, slot: str, action: str, arg: Any):
        """Every event of a rendered view (render.render_component), wherever it is placed.

        slot says which view ('tab:<name>', 'cell:<id>'). The change goes into that slot's Ui
        (render.apply_event) and the view is redrawn. Two fetch, so they are here: 'page' gets
        another page of a video search, 'form_run' runs the view's tool form (tool_forms.py);
        either puts the new result in the slot.
        """
        session = self._session()
        view = session.view_at(slot)
        if view is None:
            return
        ui = session.ui.setdefault(slot, Ui())
        if action == "form_run":
            async for update in self._run_form(slot, view, ui, dict(arg or {})):
                yield update
            return
        # an event that changes what the tool is asked for, eg a usage view's Offline / Online
        if (inputs := rerun_inputs(view, action, arg)) is not None:
            async for update in self._run_form(slot, view, ui, inputs):
                yield update
            return
        if action in ("db_run", "db_open"):
            async for update in self._run_query(slot, view, ui, action, str(arg)):
                yield update
            return
        if action == "form_reset":
            if session.restore_original(slot):
                self._new_result(slot, ui)
            return
        if action != "page":
            apply_event(view, ui, action, arg)
            self._show(slot)
            return
        current = view.value
        if ui.paging or not isinstance(current, MatchVideos) or not 1 <= current.page + arg <= current.pages:
            return
        ui.paging, ui.error = True, ""
        self._show(slot)
        yield
        try:
            with self._log_context("view", slot=slot):
                page = await asyncio.to_thread(search_videos, **current.query.model_dump(), page=current.page + arg)
        except Exception as error:  # noqa: BLE001  # network / site errors are shown in the view
            ui.error = f"Couldn't load that page: {error}"
        else:
            session.put(slot, page)
        ui.paging = False
        if slot.startswith(("tab:", "chat:")):
            self._sync()  # the tab's label changes with the page (and it redraws chat slots)
        else:
            self._show(slot)
        self._refresh_debug()

    async def _run_form(self, slot: str, view: Any, ui: Ui, inputs: dict[str, Any]):
        """Run a view's tool with the form's inputs; the result replaces the value at the slot."""
        form = form_for(view.value)
        if form is None or ui.running:
            return
        ui.running, ui.error = True, ""
        self._show(slot)
        yield
        session = self._session()
        try:
            with self._log_context("form", slot=slot):
                result, used = await asyncio.to_thread(form.run, inputs)
        except Exception as error:  # noqa: BLE001  # bad input / site errors are shown in the view
            ui.error = f"{form.title}: {error}"
        else:
            session.put(slot, result, inputs=used)
        ui.running = False
        self._new_result(slot, ui, replaced=not ui.error)
        self._refresh_debug()

    async def _run_query(self, slot: str, view: Any, ui: Ui, action: str, arg: str):
        """Run a SmashDb console's query; the console with the result replaces the one at the slot.
        db_run: arg is the SQL ("" = the editor's text, for the Run button). db_open: arg is a
        table, shown whole (and written in the editor). A failed query leaves the last result and
        shows its traceback, as a Python cell would."""
        console = view.value
        if not isinstance(console, DbConsole) or ui.running:
            return
        if action == "db_open":
            sql = f'select * from "{arg}"'
            ui.draft, ui.db_resets = sql, ui.db_resets + 1
        else:
            sql = arg or ui.draft or console.sql
        if not clean_sql(sql):
            return
        ui.running = True
        self._show(slot)
        yield
        try:
            result = await asyncio.to_thread(console.run, sql)
        except Exception as error:  # noqa: BLE001  # any bad query is shown in the view
            parts = trace_parts(error, error.__traceback__)
            ui.trace = {**_trace_fields(parts), "text": "".join(traceback.format_exception(error))}
        else:
            # a new table: what was done to the old one (its SQL on self, sort, filter) is gone
            ui.trace, ui.sql, ui.sort_col, ui.descending, ui.query = {}, "", "", False, ""
            ui.sql_resets += 1
            self._session().put(slot, result)
        ui.running = False
        if slot.startswith(("tab:", "chat:")):
            self._sync()  # the tab's label changes with the result
        else:
            self._show(slot)

    def _new_result(self, slot: str, ui: Ui, replaced: bool = True) -> None:
        """Redraw a slot after its tool form ran (or was reset); replaced = it holds another result."""
        if replaced:
            # its own inputs in the form, no video picked
            ui.runs += 1
            ui.error = ""
            ui.playing, ui.list_hidden, ui.autoplay = {}, False, False
        if slot.startswith(("tab:", "chat:")):
            self._sync()  # the tab's label changes (and it redraws chat slots)
        else:
            self._show(slot)

    @rx.event
    def open_add_menu(self, info: dict[str, Any]):
        """The Results tab bar's "+": a menu of the widgets that can be added by hand, at the pointer."""
        self.menu_tab = ""
        self.add_menu, self.add_menu_centered = True, False
        self.menu_x, self.menu_y = int(info.get("client_x", 0)), int(info.get("client_y", 0))

    @rx.event
    def toggle_add_menu(self):
        """Shortcut.ADD_WIDGET: the same menu from the keyboard, in the middle of the window
        (there is no pointer, and the Results pane with its "+" may be hidden)."""
        self.menu_tab = ""
        self.add_menu, self.add_menu_centered = not self.add_menu, True

    @rx.event
    def add_widget(self, kind: str):
        """Add a widget by hand, as a new tab: a tool form to fill in and run (a ToolRequest until
        its first run), or the widget's own blank value (eg a SmashDb console)."""
        self.add_menu = False
        widget = widget_of(kind)
        session = self._session()
        value = widget.blank(session) if widget and widget.addable else None
        if value is None:
            return
        name = session.bind_result(value, source=widget.form.key if widget.form else widget.kind)
        session.ui[f"tab:{name}"] = Ui(form_open=True)
        self._reveal_results()
        self._sync(prefer=name)

    def _reveal_results(self) -> None:
        """Make sure the results pane is on screen (eg a video was opened from a zoomed cell)."""
        self.show_results = True
        if self.zoomed != "results":
            self.zoomed = ""

    @rx.event
    def toggle_zoom(self, pane: str):
        """Fill the window with one pane, or go back to the normal layout (button, Shortcut.FULL_SCREEN)."""
        self.zoomed = "" if self.zoomed == pane else pane

    @rx.event
    def toggle_pane(self, pane: str):
        """Bottom bar: show or hide the chat, results or Python pane."""
        name = f"show_{pane}"
        if pane not in ("chat", "results", "python"):
            return
        if self.zoomed:
            # leaving full screen: the clicked pane is the one wanted back, so make sure it shows
            self.zoomed = ""
            setattr(self, name, True)
        else:
            setattr(self, name, not getattr(self, name))

    def _new_cell(self) -> Cell:
        self.cell_seq += 1
        return Cell(id=f"c{self.cell_seq}")

    def _cell_index(self, cell_id: str) -> int:
        return next((i for i, cell in enumerate(self.cells) if cell.id == cell_id), -1)

    def _update(self, index: int, **changes: Any) -> None:
        # Replace the item rather than mutating it, so Reflex always sees the change.
        self.cells[index] = dataclasses.replace(self.cells[index], **changes)

    async def _run(self, index: int, code: str) -> None:
        """Run one cell's code in the session and store its output on the cell."""
        session = self._session()
        cell_id = self.cells[index].id
        before = set(session.tabs())
        # exec blocks, so keep it off the event loop
        with self._log_context("cell", slot=f"cell:{cell_id}"):
            result = await asyncio.to_thread(session.run_python, code, f"In [{self.exec_count + 1}]")
        self.exec_count += 1
        if result.view is None:
            session.outputs.pop(cell_id, None)
        else:
            session.outputs[cell_id] = result.view
        session.ui.pop(f"cell:{cell_id}", None)  # a new result starts fresh
        self._update(
            index,
            code=code,
            count=str(self.exec_count),
            stdout=result.stdout.rstrip(),
            text=result.result_repr.rstrip(),
            error=result.error.rstrip(),
            **_trace_fields(result.trace),
            view=session.show(f"cell:{cell_id}", compact=True),
        )
        # a new name, or a closed tab's name bound to something new
        new = [name for name in session.tabs() if name not in before]
        self._sync(prefer=new[-1] if new else "")
        self._refresh_debug()

    async def _start(self, index: int, code: str):
        self.running = True
        self._update(index, count="*")
        yield
        await self._run(index, code)
        self.running = False

    @rx.event
    async def run_cell(self, cell_id: str, code: str, advance: bool):
        """Run a cell with the editor's current text. advance (Shortcut.RUN_AND_ADVANCE) on the last cell appends a new one."""
        index = self._cell_index(cell_id)
        if index < 0 or self.running:
            return
        self._update(index, code=code)
        if advance and index == len(self.cells) - 1:
            self.cells.append(self._new_cell())
        if not code.strip():
            return
        async for update in self._start(index, code):
            yield update

    @rx.event
    async def run_saved(self, cell_id: str):
        """Run button: the click blurs the editor first, so the cell's saved text is current."""
        index = self._cell_index(cell_id)
        if index < 0 or self.running or not self.cells[index].code.strip():
            return
        async for update in self._start(index, self.cells[index].code):
            yield update

    @rx.event
    async def run_all(self):
        if self.running:
            return
        self.running = True
        for index in range(len(self.cells)):
            code = self.cells[index].code
            if not code.strip():
                continue
            self._update(index, count="*")
            yield
            await self._run(index, code)
            yield
        self.running = False

    @rx.event
    def open_output(self, cell_id: str):
        """Bind a cell's result to a name (out<n>) so it also gets a tab."""
        index = self._cell_index(cell_id)
        session = self._session()
        view = session.outputs.get(cell_id)
        if index < 0 or view is None:
            return
        name = f"out{self.cells[index].count}"
        session.namespace[name] = view.value
        session.closed.pop(name, None)
        session.sources[name] = f"cell [{self.cells[index].count}]"
        self._sync(prefer=name)

    @rx.event
    def save_code(self, cell_id: str, code: str):
        """Keep an edited-but-not-run cell's text (sent when the cell loses focus)."""
        index = self._cell_index(cell_id)
        if index >= 0:
            self._update(index, code=code)

    @rx.event
    def add_cell(self):
        self.cells.append(self._new_cell())

    @rx.event
    def delete_cell(self, cell_id: str):
        index = self._cell_index(cell_id)
        if index >= 0 and not self.running:
            del self.cells[index]
            self._session().outputs.pop(cell_id, None)
            self._session().ui.pop(f"cell:{cell_id}", None)
        if not self.cells:
            self.cells.append(self._new_cell())

    @rx.event
    def clear_outputs(self):
        self._session().outputs.clear()
        for index in range(len(self.cells)):
            self._update(index, stdout="", text="", error="", **_trace_fields([]), view=ViewData())

    @rx.event(background=True)
    async def send_chat(self, form: dict[str, Any]):
        prompt = str(form.get("prompt", "")).strip()
        async with self:
            if not prompt or self.busy:
                return
            self.busy = True
            self.streaming = ""
            self.turn_seq += 1
            turn = f"turn-{self.turn_seq}"
            self.chat.append(ChatItem(kind="user", text=prompt, key=turn))
            session = self._session()
            log_context = self._log_context("chat", turn=turn)

        async def on_delta(delta: str) -> None:
            async with self:
                self.streaming += delta

        with log_context:
            result = await session.ask(prompt, on_delta)

        async with self:
            last_table = ""
            for step in result.steps:
                key = f"call-{step.call_id}" if step.call_id else ""
                self.chat.append(ChatItem(kind="step", name=step.tool, text=step.args, key=key))
                if step.result_name:
                    last_table = step.result_name
                    text = f"{step.tool} · {step.result_label}"
                    # some widgets start unfolded in the chat (widgets.py); _sync below fills their view
                    widget = widget_of(step.result_kind)
                    opened = bool(widget and widget.chat_open)
                    self.chat.append(ChatItem(kind="ref", name=step.result_name, text=text, open=opened))
            if result.text or self.streaming:
                self.chat.append(ChatItem(kind="agent", text=result.text or self.streaming))
            if result.error:
                self.chat.append(ChatItem(kind="error", text=result.error, **_trace_fields(result.trace)))
            self.streaming = ""
            self.busy = False
            self._sync(prefer=last_table)
            self._refresh_debug()
